from __future__ import annotations
import base64, subprocess, tempfile, zlib
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
PAYLOAD = ''
patch = zlib.decompress(base64.b64decode(PAYLOAD))
with tempfile.NamedTemporaryFile(suffix=".patch", delete=False) as handle:
    handle.write(patch)
    patch_path = handle.name
subprocess.run(["git", "apply", "--check", patch_path], cwd=ROOT, check=True)
subprocess.run(["git", "apply", patch_path], cwd=ROOT, check=True)
print("Applied distinct Carnage archetypes and close-up renderer.")
